import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be greater than zero")
    system = platform.system()
    data = []
    start_time = time.time()
    try:
        while time.time() - start_time < duration:
            timestamp = time.time()
            if system == "Windows":
                result = subprocess.run(['wmic', 'cpu', 'get', 'loadpercentage'], capture_output=True, text=True, shell=True)
                lines = result.stdout.strip().split('\n')
                cpu_usage = lines[1].strip() if len(lines) > 1 else "0"
            else:
                result = subprocess.run(['top', '-bn1'], capture_output=True, text=True, shell=True)
                for line in result.stdout.split('\n'):
                    if 'Cpu(s)' in line:
                        cpu_usage = line.split()[1].replace('%', '')
                        break
                else:
                    cpu_usage = "0"
            data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
            time.sleep(interval)
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(data, f)
        return LOGFILE_PATH
    except IOError:
        return None

